arguments.rule_content:
{
  "title": "After-hours File Share Access",
  "id": "RULE-2026-001",
  "status": "test",
  "description": "Detects access to sensitive file shares outside defined business hours (00:00-08:00 UTC).",
  "author": "SOC",
  "logsource": {
    "product": "windows",
    "service": "file",
    "category": "file_event"
  },
  "detection": {
    "selection": {
      "EventID": 5140,
      "ShareName|contains": "\\\\shared\\\\quarterly_reports",
      "User": "*"
    },
    "time_filter": {
      "EventTime|gte": "00:00",
      "EventTime|lt": "08:00"
    },
    "condition": "selection and time_filter"
  },
  "falsepositives": ["Authorized after‑hours maintenance"],
  "level": "low"
}
